actions.script:
const pairingCode = String(code || '').trim() || ec.web.sessionAttributes.edgePairingCode || ''
if (!pairingCode) { ec.message.addError(ec.l10n.localize('Enter the pairing code made on the edge node')); return }
ec.service.sync().name('org.moqui.edge.EdgeServices.pair#EdgeNode')
    .parameters({url: url, code: pairingCode, expectFingerprint: expectFingerprint}).call()
if (!ec.message.hasError()) { ec.web.sessionAttributes.remove('edgePairingCode'); ec.web.sessionAttributes.remove('edgeCheck') }

const L = (text) => ec.l10n.localize(text)
checked = false
checkError = ''
if (!url) return
// step 1's answer for this address, else a probe (Practices-App-Dev §4): a failed check is shown, not raised
let kept = null
try { kept = JSON.parse(ec.web.sessionAttributes.edgeCheck || 'null') } catch (e) { kept = null }
let out = kept && kept.url === url ? kept : null
if (!out) {
    ec.message.pushErrors()
    try {
        out = ec.service.sync().name('org.moqui.edge.EdgeServices.check#EdgeNode').parameter('url', url).call() || {}
        if (ec.message.hasError()) checkError = ec.message.getErrorsString()
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
    if (checkError) return
}
checked = true
compatible = out.compatible !== false
compatibleMessage = out.message || ''
hasCode = !!ec.web.sessionAttributes.edgePairingCode
const list = (items) => Array.from(items || []).join(', ')
edge = {edgeName: out.edgeName || '', fingerprint: out.fingerprint || '',
    versionText: (out.binaryVersion || '') + (out.linkVersion ? ' · ' + L('link') + ' ' + out.linkVersion : ''),
    publicNamesText: list(out.publicNames), featuresText: list(out.features)}
pair = {url: url, expectFingerprint: out.fingerprint || ''}
